import "server-only";

import type { SongScores } from "@gt/domain/audio.yue2";
import { err, type Result } from "@gt/domain/errors";
import type { Store } from "@gt/kernel/store";

// A TAKE'S SONG SCORES (spark yue2-song-lab, WP0 stub -> WP2): the DERIVED kernel table
// `audio_song_scores`, keyed (sha, scorer_version), regenerated by the `yue2-score` producer (WP3).
// LUFS / true peak are not here: they are `audio_measures` (the media-facts pass).

/** The newest-scorer row per sha; a sha never scored is absent. */
export function readSongScores(store: Store, shas: readonly string[]): Result<Readonly<Record<string, SongScores>>> {
  void store;
  void shas;
  return err("unavailable", "yue2: song scores are not built yet (WP2)");
}

/** Write one row (replaces the row of the same sha and scorer version). */
export function putSongScores(store: Store, row: SongScores): Result<SongScores> {
  void store;
  void row;
  return err("unavailable", "yue2: song scores are not built yet (WP2)");
}
